	@Override
	public void setupAnim(T entity, float limbSwing, float limbSwingAmount, float ageInTicks, float netHeadYaw, float headPitch) {
		headJoint.yRot = netHeadYaw / (180F / (float)Math.PI);
		headJoint.xRot = headPitch / (180F / (float)Math.PI);
		rLeg01a.zRot = Mth.cos(limbSwing * 0.6662F) * 0.7F * limbSwingAmount + 1.0471975511965976F;
		lLeg01a.zRot = Mth.cos(limbSwing * 0.6662F + (float)Math.PI) * 0.7F * limbSwingAmount -1.0471975511965976F;
		lLeg02a.yRot = Mth.cos(limbSwing * 0.6662F + (float)Math.PI) * 0.7F * limbSwingAmount -0.4886921905584123F;
		float animation = Mth.sin((limbSwing * 0.4F + 2) * 1.5F) * 0.3F * limbSwingAmount * 0.3F;
		float flap = Mth.sin(entity.tickCount * 0.2F) * 0.3F;
		float flap2 = Mth.cos(entity.tickCount * 0.2F) * 0.4F;
		float flap3 = Mth.cos(entity.tickCount * 0.2F) * 0.5F;
		lspike01a.yRot = flap *0.1F + 0.1f + animation * 0.4f + 0.2792526803190927F;
		lspike02a.yRot = flap2 *0.1F + 0.1f + animation * 0.4f;
		lspike03a.yRot = flap3 *0.1F + 0.1f + animation * 0.4f -0.4363323129985824F;
		lspike04a.yRot = flap *0.1F + 0.1f + animation * 0.4f -0.7155849933176751F;
		lspike05a.yRot = flap2 *0.1F + 0.1f + animation * 0.4f + 0.2792526803190927F;
		lspike06a.yRot = flap3 *0.1F + 0.1f + animation * 0.4f -0.2792526803190927F;
		rspike01a.yRot = flap *0.05F - 0.1f + animation * 0.4f -0.2792526803190927F;
		rspike02a.yRot = flap2 *0.05F - 0.1f + animation * 0.4f;
		rspike03a.yRot = flap3 *0.05F - 0.1f + animation * 0.4f + 0.4363323129985824F;
		rspike04a.yRot = flap *0.05F - 0.1f + animation * 0.4f + 0.7155849933176751F;
		rspike05a.yRot = flap2 *0.05F - 0.1f + animation * 0.4f -0.2792526803190927F;
		rspike06a.yRot = flap3 *0.05F - 0.1f + animation * 0.4f + 0.2792526803190927F;
		//		lspike01a;
		//		lspike02a;
		//		lspike03a;
		//		lspike04a;
		//		lspike05a;
		//		lspike06a;
	}

